 main.py (backend, Python 3.11 + FastAPI)

python
#!/usr/bin/env python3
# main.py – egyszerű, üzemkész Agent Router GPT-5 chat-backend

from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
import httpx
import uvicorn

# A felhasználó által kért beégetett kulcs – kizárólag a kérésedre szerepel így.
AGENT_ROUTER_API_KEY = "sk-sgwIT3Xu1B2hkehVuUHDhjTDjprGS4nGi4jphYRidZri3tdk"
AGENT_ROUTER_BASE   = "https://api.agentrouter.org/v1/chat/completions"
MODEL_NAME          = "gpt-5"

app = FastAPI(title="AgentRouter GPT-5 Chat")

# Egyszerű CORS a static index.html felől érkező hívásokhoz
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["POST"],
    allow_headers=["*"],
)

class ChatRequest(BaseModel):
    message: str

class ChatResponse(BaseModel):
    reply: str
    tokens_used: int

@app.post("/chat", response_model=ChatResponse)
async def chat(req: ChatRequest):
    """Forward user prompt to Agent Router GPT-5 and stream back the answer."""
    headers = {
        "Authorization": f"Bearer {AGENT_ROUTER_API_KEY}",
        "Content-Type":  "application/json"
    }
    payload = {
        "model": MODEL_NAME,
        "messages": [
            { "role": "system",
              "content": "You are a helpful assistant." },
            { "role": "user",
              "content": req.message }
        ]
    }

    async with httpx.AsyncClient(timeout=30) as client:
        r = await client.post(AGENT_ROUTER_BASE, headers=headers, json=payload)
    if r.status_code != 200:
        raise HTTPException(status_code=r.status_code,
                            detail=f"Agent Router error: {r.text}")

    data = r.json()
    reply_text  = data["choices"][0]["message"]["content"]
    tokens_used = data.get("usage", {}).get("total_tokens", 0)
    return ChatResponse(reply=reply_text, tokens_used=tokens_used)

if __name__ == "__main__":
    uvicorn.run("main:app", host="0.0.0.0", port=8000, reload=False)


