  </div>

<script>
const log   = document.getElementById('log');
const input = document.getElementById('input');
document.getElementById('send').onclick = async () => {
  const text = input.value.trim();
  if (!text) return;
  addMsg(text, 'user');
  input.value = '';
  const res = await fetch('http://localhost:8000/chat', {
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({message:text})
  });
  if(!res.ok){
      addMsg('Hiba: '+res.statusText, 'bot');return;
  }
  const data = await res.json();
  addMsg(data.reply + ` \n\n(token: ${data.tokens_used})`, 'bot');
};
function addMsg(txt, cls){
  const d=document.createElement('div');
  d.className='msg '+cls;
  d.textContent=txt;
  log.appendChild(d);
  log.scrollTop=log.scrollHeight;
}
</script>
</body>
</html>


 futtatás

1. python -m venv venv && source venv/bin/activate
2. pip install fastapi uvicorn httpx
3. python main.py  →  backend a http://localhost:8000 címen  
4. Megnyitod böngészőben az index.htmlt, és már megy is a GPT5 chat.

Így egyetlen gépből (main.py) és egyetlen statikus kliensfájlból (index.html) álló, teljes értékű rendszert kapsz, ahol a frontend fetchkérés → FastAPI → Agent Router GPT5 útvonalon beszélget a modellel.

